      "element_id": "prisma_2020_5_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The review does not distinguish between exclusion due to outcomes not being measured versus exclusion due to outcome results not being reported. The exclusion list in text_7 simply groups these as 'not reporting relevant outcomes'."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Subgroup analyses by income setting (high-income vs. low-and middle-income) and accreditation body (JCI vs. national) were planned a priori.",
      "reason": "The review specifies the groups used for synthesis (subgroup analyses) and the narrative synthesis approach."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Studies that reported the construct only qualitatively, used non-convertible categorical outcomes, or lacked dispersion statistics were excluded from pooling and analysed narratively.",
      "reason": "The review provides a clear rationale for excluding studies from the meta-analysis (pooling) based on the nature of the reported data."
    }
