{
  "item_id": "PRISMA_2020_13a",
  "elements": [
    {
      "element_id": "prisma_2020_13a_e1",
      "status": "PRESENT",
      "chunk_id": "text_6",
      "quote": "Outcome commensurability for the meta-analysis was defined a priori as: (i) measurement of the same construct (healthcare-quality score derived from accreditationaligned domains - patient safety, organizational performance, and quality of care); (ii) reporting of effect on continuous scale convertible to standardized mean difference (SMD); and (iii) availability of pre-and post-accreditation comparator data, or accredited vs. non-accredited group comparison, with sample sizes and dispersion statistics. Studies that reported the construct only qualitatively, used non-convertible categorical outcomes, or lacked dispersion statistics were excluded from pooling and analysed narratively.",
      "reason": "The authors explicitly describe the criteria and process used to determine which studies were eligible for meta-analysis (pooling) versus narrative synthesis, based on the nature of the reported outcomes and statistical data."
    }
  ],
  "confidence": 100
}

{
